"use client";

import React, { useState, useRef } from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";

export interface HoldButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label?: string;
  onComplete?: () => void;
}

export function HoldButton({
  label = "Hold to Activate",
  onComplete,
  className,
  ...props
}: HoldButtonProps) {
  const [progress, setProgress] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const [isDone, setIsDone] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  const startHold = () => {
    if (isDone) return;
    setIsHolding(true);
    intervalRef.current = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) {
          clearInterval(intervalRef.current!);
          setIsDone(true);
          onComplete?.();
          return 100;
        }
        return prev + 4;
      });
    }, 40);
  };

  const stopHold = () => {
    if (isDone) return;
    setIsHolding(false);
    if (intervalRef.current) clearInterval(intervalRef.current);
    setProgress(0);
  };

  const reset = () => {
    setIsDone(false);
    setProgress(0);
  };

  return (
    <button
      type="button"
      onMouseDown={startHold}
      onMouseUp={stopHold}
      onMouseLeave={stopHold}
      onTouchStart={startHold}
      onTouchEnd={stopHold}
      onClick={isDone ? reset : undefined}
      className={cn(
        "relative overflow-hidden rounded-2xl bg-zinc-900 px-6 py-3 text-sm font-semibold text-white shadow-md border border-zinc-800 transition-all select-none cursor-pointer",
        className
      )}
      {...props}
    >
      <div
        className="absolute inset-y-0 left-0 bg-blue-600/80 transition-all duration-75"
        style={{ width: `${progress}%` }}
      />
      <span className="relative z-10 flex items-center justify-center gap-2">
        {isDone ? (
          <>
            <Check className="h-4 w-4 text-emerald-400" />
            <span>Activated!</span>
          </>
        ) : (
          <span>{isHolding ? "Holding..." : label}</span>
        )}
      </span>
    </button>
  );
}

export default HoldButton;
